#include <SPI.h>
#include <MFRC522.h>
#include <Servo.h>

// --- Пины RFID ---
#define RST_PIN 5
#define SS_PIN 53

// --- Пины исполнительных устройств ---
#define SERVO_PIN 9
#define BUZZER_PIN 8

MFRC522 rfid(SS_PIN, RST_PIN);
Servo doorServo;

bool doorOpen = false;
unsigned long doorOpenTime = 0;
const unsigned long doorOpenDuration = 5000; // Дверь открыта 5 секунд

void setup() {
  Serial.begin(9600);
  SPI.begin();
  rfid.PCD_Init();

  pinMode(BUZZER_PIN, OUTPUT);

  doorServo.attach(SERVO_PIN);
  doorServo.write(0); // Изначально замок закрыт

  // Короткий писк при включении питания
  tone(BUZZER_PIN, 1000, 200); 
  delay(1000);
}

void loop() {
  // 1. Проверка RFID (поиск карты)
  if (rfid.PICC_IsNewCardPresent() && rfid.PICC_ReadCardSerial()) {
    if (!doorOpen) {
      openDoor();
    }
    rfid.PICC_HaltA(); // Завершаем общение с картой
  }

  // 2. Автоматическое закрытие двери через заданное время
  if (doorOpen && (millis() - doorOpenTime > doorOpenDuration)) {
    closeDoor();
  }
}

void openDoor() {
  doorOpen = true;
  doorOpenTime = millis();

  // Сигнал успеха (два писка)
  tone(BUZZER_PIN, 1000, 100);
  delay(150);
  tone(BUZZER_PIN, 1500, 100);

  doorServo.write(90); // Открыть
  Serial.println("Доступ разрешен. Дверь открыта.");
}

void closeDoor() {
  doorOpen = false;

  doorServo.write(0); // Закрыть
  Serial.println("Дверь закрыта.");
}
